// AUTOGENERATED by gen-vue. Do not edit.

import {
  computed,
  onBeforeUnmount,
  onMounted,
  type Ref,
  ref,
  type ShallowRef,
  shallowRef,
  useId,
  watch,
} from "vue";

const RESPONSIVE_KEYS = ["base", "md", "lg", "xl", "2xl"] as const;

type Breakpoint = (typeof RESPONSIVE_KEYS)[number];

export type Responsive<T> = T | Partial<Record<Breakpoint, T>>;

// matchMedia queries baked from specs/_breakpoints.yaml. Single source.
const BREAKPOINT_QUERIES: Partial<Record<Breakpoint, string>> = {
  md: "(min-width: 48rem)",
  lg: "(min-width: 64rem)",
  xl: "(min-width: 80rem)",
  "2xl": "(min-width: 96rem)",
};

function readActiveBreakpoint(): Breakpoint {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return "base";
  for (let i = RESPONSIVE_KEYS.length - 1; i > 0; i--) {
    const key = RESPONSIVE_KEYS[i];
    if (!key) continue;
    const q = BREAKPOINT_QUERIES[key];
    if (q && window.matchMedia(q).matches) return key;
  }
  return "base";
}

/** Reactive active-breakpoint key. Drives `Responsive<T>` runtime behavior. */
export function useActiveBreakpoint(): Readonly<Ref<Breakpoint>> {
  const active = ref<Breakpoint>(readActiveBreakpoint());
  const cleanups: Array<() => void> = [];
  onMounted(() => {
    const onChange = () => {
      active.value = readActiveBreakpoint();
    };
    for (const key of RESPONSIVE_KEYS) {
      if (key === "base") continue;
      const q = BREAKPOINT_QUERIES[key];
      if (!q) continue;
      const mql = window.matchMedia(q);
      mql.addEventListener("change", onChange);
      cleanups.push(() => mql.removeEventListener("change", onChange));
    }
  });
  onBeforeUnmount(() => {
    for (const fn of cleanups) fn();
  });
  return active;
}

/** Resolve a `Responsive<boolean>` at the active breakpoint (mobile-first cascade). */
export function isActiveAt(value: unknown, bp: Breakpoint): boolean {
  if (value === true) return true;
  if (value == null || value === false) return false;
  if (typeof value !== "object") return false;
  const obj = value as Partial<Record<Breakpoint, boolean>>;
  const idx = RESPONSIVE_KEYS.indexOf(bp);
  for (let i = idx; i >= 0; i--) {
    const key = RESPONSIVE_KEYS[i];
    if (key && key in obj) return obj[key] === true;
  }
  return false;
}

export function responsiveDataAttrs(
  name: string,
  value: unknown,
): Record<string, string | undefined> {
  if (value == null || value === false) return {};
  if (typeof value === "object") {
    // Emit every declared key (including `false` at non-base) — the CSS
    // override pattern needs the explicit attribute to match against.
    const obj = value as Record<string, unknown>;
    const out: Record<string, string | undefined> = {};
    for (const key of RESPONSIVE_KEYS) {
      const v = obj[key];
      if (v == null) continue;
      // `base: false` has no attribute (absence-of) — emitting "false" would never match.
      if (key === "base" && v === false) continue;
      const attr = key === "base" ? `data-${name}` : `data-${name}-${key}`;
      out[attr] = v === true ? "true" : v === false ? "false" : String(v);
    }
    return out;
  }
  return { [`data-${name}`]: value === true ? "true" : String(value) };
}

// ── Overlay composable — used by composite overlay components ──────────────

type OverlayInteraction = {
  on: { event: string; target?: string; key?: string };
  do: "open" | "close" | "toggle";
  /** Number or reactive getter — Vue's setup runs once, so re-read on fire. */
  delayMs?: number | (() => number);
  when?: string;
};

type OverlayConfig = {
  /** Getter for the controlled prop (setup runs once; re-read each render). */
  open?: () => boolean | undefined;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  anchorVar: string;
  popoverMode: "auto" | "manual" | "hint";
  interactions: ReadonlyArray<OverlayInteraction>;
  /** Getter for `Responsive<boolean>`; gated against the active breakpoint. */
  disabled?: () => unknown;
};

type OverlayHandlers = Record<string, (event: Event) => void>;

type OverlayReturn = {
  open: Readonly<Ref<boolean>>;
  setOpen: (next: boolean) => void;
  anchorName: string;
  anchorVar: string;
  popoverId: string;
  popoverMode: "auto" | "manual" | "hint";
  contentRef: ShallowRef<HTMLElement | null>;
  triggerHandlers: OverlayHandlers;
};

function sanitizeId(id: string): string {
  return id.replace(/[^a-zA-Z0-9_-]/g, "");
}

// `:popover-open` throws SyntaxError on engines that don't recognize it; probe once.
const SUPPORTS_POPOVER_OPEN_SELECTOR =
  typeof CSS !== "undefined" &&
  typeof CSS.supports === "function" &&
  CSS.supports("selector(:popover-open)");

function popoverIsOpen(node: HTMLElement): boolean | undefined {
  if (!SUPPORTS_POPOVER_OPEN_SELECTOR) return undefined;
  try {
    return node.matches(":popover-open");
  } catch {
    return undefined;
  }
}

/** State machine + popover toggle + anchor binding + event wiring for overlay composites. */
export function useOverlay(config: OverlayConfig): OverlayReturn {
  const internalOpen = ref<boolean>(config.defaultOpen ?? false);
  const open = computed<boolean>(() => {
    const fromProp = config.open?.();
    return fromProp !== undefined ? fromProp : internalOpen.value;
  });

  const activeBp = useActiveBreakpoint();

  const setOpen = (next: boolean) => {
    const fromProp = config.open?.();
    if (fromProp === undefined) internalOpen.value = next;
    config.onOpenChange?.(next);
  };

  const idCore = sanitizeId(useId());
  const anchorName = `--t-${idCore}`;
  const popoverId = `t-overlay-${idCore}`;

  const contentRef = shallowRef<HTMLElement | null>(null);

  let openTimer = 0;
  let closeTimer = 0;
  const clearTimers = () => {
    if (openTimer) window.clearTimeout(openTimer);
    if (closeTimer) window.clearTimeout(closeTimer);
    openTimer = 0;
    closeTimer = 0;
  };

  const schedule = (action: "open" | "close" | "toggle", delayMs: number) => {
    if (isActiveAt(config.disabled?.(), activeBp.value)) return;
    clearTimers();
    const next = action === "toggle" ? !open.value : action === "open";
    if (delayMs <= 0) {
      setOpen(next);
      return;
    }
    if (action === "close") {
      closeTimer = window.setTimeout(() => setOpen(next), delayMs);
    } else {
      openTimer = window.setTimeout(() => setOpen(next), delayMs);
    }
  };

  onBeforeUnmount(() => clearTimers());

  // Drive Popover API from `open`. `immediate` covers `defaultOpen: true`;
  // `flush: 'post'` waits for DOM update.
  watch(
    open,
    (current) => {
      const node = contentRef.value;
      if (!node) return;
      const popoverState = popoverIsOpen(node);
      if (current && popoverState !== true) {
        try {
          node.showPopover();
        } catch {}
      } else if (!current && popoverState !== false) {
        try {
          node.hidePopover();
        } catch {}
      }
    },
    { immediate: true, flush: "post" },
  );

  // Re-read getter-form delays per fire (latest prop value).
  const resolveDelay = (d: number | (() => number) | undefined): number => {
    if (d === undefined) return 0;
    return typeof d === "function" ? d() : d;
  };

  // Document/window-bound rules. Mount/unmount with the composable.
  const cleanups: Array<() => void> = [];
  onMounted(() => {
    for (const rule of config.interactions) {
      const target = rule.on.target;
      if (target !== "document" && target !== "window") continue;
      const sink: EventTarget = target === "document" ? document : window;
      const handler = (event: Event) => {
        if (rule.when === "open" && !open.value) return;
        if (rule.on.key && event instanceof KeyboardEvent && event.key !== rule.on.key) return;
        schedule(rule.do, resolveDelay(rule.delayMs));
      };
      sink.addEventListener(rule.on.event, handler);
      cleanups.push(() => sink.removeEventListener(rule.on.event, handler));
    }
  });
  onBeforeUnmount(() => {
    for (const fn of cleanups) fn();
  });

  // Trigger-bound rules → handlers spread via `v-on`. Bare event names.
  // Same-event rules compose; `when` and `on.key` filter per-fire as above.
  const triggerHandlers: OverlayHandlers = {};
  for (const rule of config.interactions) {
    if (rule.on.target !== "trigger") continue;
    const eventName = rule.on.event;
    const previous = triggerHandlers[eventName];
    triggerHandlers[eventName] = (event: Event) => {
      previous?.(event);
      if (rule.when === "open" && !open.value) return;
      if (rule.on.key) {
        if (!(event instanceof KeyboardEvent) || event.key !== rule.on.key) return;
      }
      schedule(rule.do, resolveDelay(rule.delayMs));
    };
  }

  return {
    open,
    setOpen,
    anchorName,
    anchorVar: config.anchorVar,
    popoverId,
    popoverMode: config.popoverMode,
    contentRef,
    triggerHandlers,
  };
}
